"use client"
import { DataTable } from "@/components/blocks/data-table"
const rows = [{ id: "task-1", title: "Review changes" }]
export function Tasks() {
  return <DataTable rows={rows} caption="Tasks"
    getRowId={row => row.id} getRowLabel={row => row.title}
    columns={[{ id: "title", header: "Title", cell: row => row.title }]} />
}

"use client"
import { WorkflowCanvas, type WorkflowCanvasProps } from "@/components/blocks/workflow-canvas"
// The caller supplies the graph, selection and command callbacks.
export function Graph(props: WorkflowCanvasProps) {
  return <div style={{ height: 400 }}><WorkflowCanvas {...props} /></div>
}

import { CanvasNode } from "@/components/ui/canvas-node"

// 在 React Flow 的自定义节点渲染器中使用。
<CanvasNode node={record} definition={definition} selected={selected} readOnly={readOnly} />

import { CanvasPort } from "@/components/ui/canvas-port"

// 在 React Flow 自定义节点上下文中使用。
<CanvasPort port={portDefinition} readOnly={readOnly} />

import { Chip } from "@/components/ui/chip"

<Chip label="TypeScript" selected={selected}
  onSelectedChange={setSelected} onRemove={removeValue} />

"use client"
import { Button } from "@/components/ui/button"
export function SaveButton() {
  return <Button onClick={() => console.log("save")}>Save</Button>
}

import { TaskPanel } from "@/components/blocks/task-panel"

<TaskPanel
  title="发布进度"
  tasks={[
    { id: "build", title: "构建应用", status: "completed" },
    { id: "deploy", title: "部署应用", status: "failed" },
  ]}
  onRetry={(id) => retryTask(id)}
/>

import { ScrollPlayground } from "@/components/blocks/scroll-playground"

